```
import React, { useState, useEffect } from 'react';

const Autocomplete = ({ options, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [selectedOption, setSelectedOption] = useState(null);

  useEffect(() => {
    const handleInputValueChange = (e) => {
      const currentValue = e.target.value;
      setInputValue(currentValue);
      const suggestions = options.filter((option) => {
        return option.toLowerCase().includes(currentValue.toLowerCase());
      });
      setSuggestions(suggestions);
    };

    document.addEventListener('input', handleInputValueChange);

    return () => {
      document.removeEventListener('input', handleInputValueChange);
    };
  }, [options]);

  const handleSelect = (option) => {
    onSelect(option);
    setInputValue(option);
    setSelectedOption(option);
  };

  const renderSuggestions = () => {
    return (
      <ul>
        {suggestions.map((option, index) => (
          <li key={index} onClick={() => handleSelect(option)}>
            {option}
          </li>
        ))}
      </ul>
    );
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        placeholder="Search"
      />
      {selectedOption ? (
        <div>
          <p>{selectedOption}</p>
          <button onClick={() => setSelectedOption(null)}>Clear</button>
        </div>
      ) : (
        renderSuggestions()
      )}
    </div>
  );
};

export default Autocomplete;
