  let dy = targetY - currentY;

  // Calculate the magnitude of the difference vector
  let magnitude = mAbs(dx) + mAbs(dy);

  // Calculate the direction of the target (NESW snap)
  let targetDirection = "";
  if (dx > 0) {
    if (dy > 0) targetDirection = "R";
    else if (dy < 0) targetDirection = "D";
    else targetDirection = "E";
  } else if (dx < 0) {
    if (dy > 0) targetDirection = "L";
    else if (dy < 0) targetDirection = "U";
    else targetDirection = "W";
  } else {
    if (dy > 0) targetDirection = "S";
    else if (dy < 0) targetDirection = "N";
  }

  // If the target direction is different from the current direction,
  // turn towards the target direction
  if (direction !== targetDirection) {
    let turnAmount = mFloor(mAbs(linemSign(direction[targetDirection])) / 4);
    TurnLike(targetDirection, turnAmount);
  }

  // If the target is within a certain distance (e.g. 5), stop moving
  if (magnitude <= 5) return;

  // Calculate the movement amount (1 unit)
  let movementAmount = 1;

  // Move in the direction of the target
  while (magnitude > 0) {
    currentX += linemSign(dx) * movementAmount;
    currentY += linemSign(dy) * movementAmount;
    magnitude -= movementAmount;
    dx -= linemSign(dx) * movementAmount;
    dy -= linemSign(dy) * movementAmount;

    // Check if the target is reached
    if (mAbs(dx) <= 1 && mAbs(dy) <= 1) return;

