class Password {
  constructor() {
    this.MIN_LENGTH = 8; // longitud mínima de la contraseña
    this.MAX_LENGTH = 128; // longitud máxima de la contraseña
    this.CHARACTERS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-='; // caracteres permitidos
  }

  generatePassword() {
    let password = '';
    for (let i = 0; i < this.MIN_LENGTH; i++) {
      password += this.CHARACTERS.charAt(Math.floor(Math.random() * this.CHARACTERS.length));
    }
    return password;
  }

  validatePassword(password) {
    if (password.length < this.MIN_LENGTH || password.length > this.MAX_LENGTH) {
      return false;
    }
    for (let i = 0; i < password.length; i++) {
      if (this.CHARACTERS.indexOf(password.charAt(i)) == -1) {
        return false;
      }
    }
    return true;
  }
}
```
