double rectangleIntegration(double (*f)(double), double a, double b, int numPoints) {
    double h = (b - a) / numPoints;
    double sum = 0;
    for (int i = 0; i < numPoints; i++) {
        sum += f(a + i * h);
    }
    return sum * h;
}

// Функция вычисления интеграла методом трапеций
double trapezoidIntegration(double (*f)(double), double a, double b, int numPoints) {
    double h = (b - a) / numPoints;
    double sum = 0.5 * (f(a) + f(b));
    for (int i = 1; i < numPoints - 1; i++) {
        sum += f(a + i * h);
    }
    return sum * h;
}

// Функция вычисления интеграла методом парабол (метод Симпсона)
double simpsonIntegration(double (*f)(double), double a, double b, int numPoints) {
    double h = (b - a) / numPoints;
    double sum = f(a) + f(b);
    for (int i = 1; i < numPoints - 1; i++) {
        sum += 2 * f(a + i * h);
    }
    return (h / 3) * sum;
}

