import { MuiThemeProvider, createTheme } from '@material-ui/core/styles';
import {CssBaseline} from '@material-ui/core';

class SessionManager extends Component {
  constructor(props) {
    super(props);
    this.state = {
      authenticated: false,
      userData: null,
      token: null
    };
  }

  async handleGoogleLogin() {
    await GoogleOAuth.authorize({ 
      client_id: 'YOUR_CLIENT_ID',
      scope: 'profile email' 
    });
  }

  async handleGoogleLogout() {
    localStorage.removeItem('token');
    this.setState({
      authenticated: false,
      userData: null,
      token: null
    });
  }

  async componentWillMount() {
    if (localStorage.getItem('token')) {
      const token = localStorage.getItem('token');
      this.setState({
        authenticated: true,
        token: token
      });
    }
  }

  async componentDidMount() {
    if (this.state.authenticated) {
      // Check if the token is still valid
      const response = await fetch(`https://oauth2.googleapis.com/tokeninfo?id_token=${this.state.token}`);
      const userData = await response.json();
      this.setState({ userData });
    }
  }

  render() {
    return (
      <MuiThemeProvider theme={createTheme({-palette: {primary: {main: '#3f51b5'}}})}>
        <CssBaseline />
        {this.state.authenticated ? (
          <div>
            <h1>Welcome, {this.state.userData.given_name}!</h1>
            <button onClick={this.handleGoogleLogout.bind(this)}>Logout</button>
          </div>
        ) : (
          <div>
            <h1>Please sign in!</h1>
            <button onClick={this.handleGoogleLogin.bind(this)}>Sign in with Google</button>
          </div>
        )}
      </MuiThemeProvider>
    );
  }
}

export default SessionManager;
