```
// Define the game board as a 2D array
var board = [];
for (var i = 0; i < 3; i++) {
  board[i] = [];
  for (var j = 0; j < 3; j++) {
    board[i][j] = 0; // 0 = empty, 1 = X, 2 = O
  }
}

// Define the AI's strategy
function AI(nextPlayer) {
  // Check if the game is over
  if (checkWin(board, nextPlayer)) {
    return board;
  }

  // Make a move
  var bestMove;
  var bestScore = -Infinity;
  for (var i = 0; i < 3; i++) {
    for (var j = 0; j < 3; j++) {
      if (board[i][j] === 0) {
        board[i][j] = nextPlayer;
        var score = minimax(board, 0, -Infinity, Infinity);
        board[i][j] = 0; // undo the move
        if (score > bestScore) {
          bestScore = score;
          bestMove = [i, j];
        }
      }
    }
  }
  board[bestMove[0]][bestMove[1]] = nextPlayer;
  return board;
}

// Define the minimax function
function minimax(board, depth, alpha, beta) {
  var player = (depth % 2 === 0) ? 1 : 2;
  if (checkWin(board, player)) {
    return (player === 1) ? 1 : -1;
  }
  var score = 0;
  for (var i = 0; i < 3; i++) {
    for (var j = 0; j < 3; j++) {
      if (board[i][j] === 0) {
        board[i][j] = player;
        score = minimax(board, depth + 1, alpha, beta);
        board[i][j] = 0; // undo the move
        if (player === 1) {
          if (score > alpha) {
            alpha = score;
          }
        } else {
          if (score < beta) {
            beta = score;
          }
        }
      }
    }
  }
  return (player === 1) ? alpha : beta;
}

// Define the checkWin function
function checkWin(board, player) {
  // Check rows and columns
  for (var i = 0; i < 3; i++) {
    if (board[i][0] === player && board[i][1] === player && board[i][2] === player) {
      return true;
    }
    if (board[0][i] === player && board[1][i] === player && board[2][i] === player) {
      return true;
    }
  }
  // Check diagonals
  if (board[0][0] === player && board[1][1] === player && board[2][2] === player) {
    return true;
  }
  if (board[0][2] === player && board[1][1] === player && board[2][0] === player) {
    return true;
  }
  return false;
}

// Start the game
var currentPlayer = 1; // X
while (true) {
  console.log(board);
  var move = AI(currentPlayer);
  console.log("AI made a move:");
  console.log(move);
  if (checkWin(move, currentPlayer)) {
    console.log("AI won!");
    break;
  }
  currentPlayer = (currentPlayer === 1) ? 2 : 1;
}
